{"sql":"WITH c AS (
  SELECT country, sum(gmv_amount) AS gmv, sum(net_amount) AS net_sales, count(DISTINCT order_id) AS orders
  FROM order_lines
  WHERE order_date >= DATE '2011-01-01' AND order_date <= DATE '2011-12-09'
  GROUP BY country
)
SELECT * FROM c ORDER BY gmv DESC OFFSET 30;
","purpose":"查看 GMV 排名 31-36 名的国家，并核对全部 36 国合计"}
